#include <iostream>
#include <cstdio>
using namespace std;

int main() {
    int a, b, c, n;
    while (scanf("%d %d %d", &a, &b, &c), a || b || c) {
        scanf("%d", &n);

        int f[300] = {2}; // Using a fixed size array with initialization
        int m = a + b + c;
        int x[1000], y[1000], z[1000];
        bool r[1000];

        for (int i = 0; i < n; i++) {
            scanf("%d %d %d %d", &x[i], &y[i], &z[i], &r[i]);
            x[i]--; y[i]--; z[i]--; // Adjust for zero indexing
        }

        int cnt = 0;
        while (cnt < 100000) {
            for (int i = 0; i < n; i++) {
                int a = x[i], b = y[i], c = z[i];
                bool Flag = r[i];
                if (Flag) {
                    f[a] = f[b] = f[c] = 1;
                } else {
                    if (f[b] == 1 && f[c] == 1) f[a] = 0;
                    if (f[a] == 1 && f[c] == 1) f[b] = 0;
                    if (f[a] == 1 && f[b] == 1) f[c] = 0;
                }
            }
            cnt++;
        }
        for (int i = 0; i < m; i++) printf("%d\n", f[i]);
    }
}

#include<iostream>
#include<vector>
#include<algorithm>
using namespace std;

int main() {
    int a, b, c, n;
    while (true) {
        cin >> a >> b >> c;
        if (!(a || b || c)) break; // Check if all inputs are zero
        cin >> n;

        int f[300];
        fill(f, f + 300, 2);
        int m = a + b + c;
        int x[1000], y[1000], z[1000];
        bool r[1000];

        for (int i = 0; i < n; i++) {
            cin >> x[i] >> y[i] >> z[i] >> r[i];
            x[i]--; y[i]--; z[i]--;
        }

        // Using a flag to track changes
        bool changed;
        do {
            changed = false; // Reset change flag for this iteration
            for (int i = 0; i < n; i++) {
                int a = x[i], b = y[i], c = z[i];
                bool Flag = r[i];
                if (Flag) {
                    if (f[a] > 1) {
                        f[a] = f[b] = f[c] = 1;
                        changed = true; // Mark that a change occurred
                    }
                } else {
                    if (f[b] == 1 && f[c] == 1) {
                        if (f[a] > 0) {
                            f[a] = 0;
                            changed = true;
                        }
                    }
                    if (f[a] == 1 && f[c] == 1) {
                        if (f[b] > 0) {
                            f[b] = 0;
                            changed = true;
                        }
                    }
                    if (f[a] == 1 && f[b] == 1) {
                        if (f[c] > 0) {
                            f[c] = 0;
                            changed = true;
                        }
                    }
                }
            }
        } while (changed); // Repeat until no changes occur

        for (int i = 0; i < m; i++) cout << f[i] << endl;
    }
}

